export const PRINT_CSS = "/* =========================================================================\n   The print contract.\n\n   One stylesheet, no build step. Headless Chromium loads this file and gets\n   the same page the browser showed, which is the only way a preview can be\n   trusted.\n\n   Two rules hold the whole thing together:\n\n   1. The page box has no margin. `@page { margin: 0 }` and the document\n      supplies its own padding, so screen and print agree on where the text\n      starts. A UA-supplied print margin is the classic reason a preview and\n      its PDF disagree by a few millimetres and then by a whole line.\n\n   2. Nothing is hardcoded. Every size, gap and leading comes from a custom\n      property set by the density ladder below, so fitting a page is a single\n      attribute change and never a per-template edit.\n   ========================================================================= */\n\n@page {\n  size: A4;\n  margin: 0;\n}\n\n/* -------------------------------------------------------------------------\n   The density ladder, ported from backend/src/atsresume/render/density.py.\n\n   The budget is spent in the order a typesetter would spend it: page margins\n   first, because generous margins are a convention and nobody misses them;\n   then the gaps between blocks, which carry structure and can tighten a long\n   way before the structure stops reading; then line spacing, which is only\n   noticeable against a comparison; and body type last.\n\n   Body type never goes below 9pt. Below that a resume fails the recruiter\n   reading it on a phone and the one printing it, so the ladder stops. Content\n   that still overflows at rung 4 is a content problem and gets reported as\n   one. See fit.ts: nothing is ever silently cut to make a page count look\n   right.\n   ------------------------------------------------------------------------- */\n\n[data-density=\"0\"] {\n  --page-pad: 0.75in;\n  --block-gap: 1;\n  --leading: 1.35;\n  --body: 11pt;\n}\n[data-density=\"1\"] {\n  --page-pad: 0.68in;\n  --block-gap: 0.88;\n  --leading: 1.3;\n  --body: 10.5pt;\n}\n[data-density=\"2\"] {\n  --page-pad: 0.6in;\n  --block-gap: 0.76;\n  --leading: 1.24;\n  --body: 10pt;\n}\n[data-density=\"3\"] {\n  --page-pad: 0.52in;\n  --block-gap: 0.65;\n  --leading: 1.18;\n  --body: 9.5pt;\n}\n[data-density=\"4\"] {\n  --page-pad: 0.45in;\n  --block-gap: 0.55;\n  --leading: 1.12;\n  --body: 9pt;\n}\n\n/* -------------------------------------------------------------------------\n   Tokens.\n\n   Spacing is expressed in em so it tracks the body size the rung chose, then\n   scaled by --block-gap so a rung can tighten structure without touching type.\n   ------------------------------------------------------------------------- */\n\n.rz {\n  --ink: #16181d;\n  --ink-soft: #3b4048;\n  --ink-mute: #5c626c;\n  --rule: #c7ccd4;\n  --rule-strong: #16181d;\n  --accent: #1c3f66;\n  --panel: #f2f4f7;\n\n  /* Type scale. Restrained: four steps, not eight. */\n  --t-name: 1.95em;\n  --t-headline: 1em;\n  --t-h2: 0.82em;\n  --t-role: 1em;\n  --t-meta: 0.93em;\n  --t-small: 0.88em;\n\n  --gap-section: calc(var(--block-gap) * 1.15em);\n  --gap-entry: calc(var(--block-gap) * 0.78em);\n  --gap-head: calc(var(--block-gap) * 0.42em);\n  --gap-line: calc(var(--block-gap) * 0.2em);\n  --rule-offset: calc(var(--block-gap) * 0.26em);\n\n  /* A4 at 96dpi. fit.ts reads this so one number defines the page. */\n  --page-w: 210mm;\n  --page-h: 297mm;\n}\n\n/* ------------------------------------------------------------- the page -- */\n\n.rz {\n  box-sizing: border-box;\n  width: var(--page-w);\n  min-height: var(--page-h);\n  padding: var(--page-pad);\n  margin: 0 auto;\n  background: #ffffff;\n  color: var(--ink);\n  font-family: \"Inter\", \"Helvetica Neue\", Helvetica, Arial, \"Liberation Sans\", sans-serif;\n  font-size: var(--body);\n  line-height: var(--leading);\n  font-variant-numeric: tabular-nums lining-nums;\n  text-rendering: geometricPrecision;\n  -webkit-font-smoothing: antialiased;\n\n  /* Accent rules and the Modern sidebar are structure, not decoration.\n     Without this Chromium drops them from the printed file. */\n  -webkit-print-color-adjust: exact;\n  print-color-adjust: exact;\n\n  /* A line stranded at the top or bottom of a page reads as a mistake. */\n  orphans: 2;\n  widows: 2;\n}\n\n.rz *,\n.rz *::before,\n.rz *::after {\n  box-sizing: inherit;\n}\n\n.rz p,\n.rz ul,\n.rz ol,\n.rz h1,\n.rz h2,\n.rz h3,\n.rz dl,\n.rz dd,\n.rz dt {\n  margin: 0;\n  padding: 0;\n}\n\n.rz ul {\n  list-style: none;\n}\n\n.rz a {\n  color: inherit;\n  text-decoration: none;\n  /* A long URL must not push the column wider than the page. */\n  overflow-wrap: anywhere;\n}\n\n.rz a:hover {\n  text-decoration: underline;\n}\n\n/* --------------------------------------------------------------- header -- */\n\n.rz-header {\n  break-after: avoid;\n  page-break-after: avoid;\n}\n\n.rz-name {\n  font-size: var(--t-name);\n  line-height: 1.05;\n  font-weight: 650;\n  letter-spacing: -0.015em;\n  color: var(--ink);\n}\n\n.rz-headline {\n  margin-top: calc(var(--block-gap) * 0.24em);\n  font-size: var(--t-headline);\n  line-height: 1.25;\n  color: var(--ink-soft);\n}\n\n.rz-contact {\n  display: flex;\n  flex-wrap: wrap;\n  margin-top: calc(var(--block-gap) * 0.42em);\n  font-size: var(--t-meta);\n  color: var(--ink-soft);\n  line-height: 1.45;\n}\n\n/* The separator is generated rather than written into the markup, so a missing\n   field can never leave a dangling divider behind. It trails its item rather\n   than leading the next one, because a wrapped contact line beginning with a\n   separator reads as a mistake.\n\n   It is a vertical bar and not the middle dot it wants to be, and that is not\n   a taste decision. Generated content is invisible to `textContent`, which is\n   what jsdom tests see, but Chromium puts it in the PDF's text layer like any\n   other glyph. The middle dot therefore extracted as U+00B7 sitting between a\n   candidate's city and their email address. sanitize.py rewrites that exact\n   character to a comma before a parser ever sees it in a bullet, for the same\n   reason it has no business in a contact line: a literal keyword match against\n   a non-ASCII neighbour is inconsistent across parsers.\n\n   backend/tests/test_template_pdf.py is what caught this, by printing the real\n   template in the real browser and reading the text back out. Neither side's\n   own suite could: jsdom has no printer, and the renderer has no opinion about\n   what it is given. */\n.rz-contact > li:not(:last-child)::after {\n  content: \"|\";\n  margin: 0 0.5em;\n  color: var(--rule);\n}\n\n/* -------------------------------------------------------------- section -- */\n\n.rz-section {\n  margin-top: var(--gap-section);\n}\n\n.rz-section:first-of-type {\n  margin-top: 0;\n}\n\n.rz-h2 {\n  font-size: var(--t-h2);\n  font-weight: 700;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  color: var(--ink);\n  padding-bottom: var(--rule-offset);\n  border-bottom: 0.6pt solid var(--rule-strong);\n  margin-bottom: calc(var(--gap-head) * 1.1);\n\n  /* A heading is never the last thing on a page. */\n  break-after: avoid;\n  page-break-after: avoid;\n  break-inside: avoid;\n}\n\n.rz-summary {\n  text-align: left;\n  max-width: 68em;\n}\n\n/* ---------------------------------------------------------------- entry -- */\n\n/* A role is one unit of meaning. Splitting it across a page break makes the\n   bullets look like they belong to the next employer. */\n.rz-entry {\n  break-inside: avoid;\n  page-break-inside: avoid;\n  margin-top: var(--gap-entry);\n}\n\n.rz-entry:first-child {\n  margin-top: 0;\n}\n\n/* Employer left, dates hard right on the same baseline. */\n.rz-entry-line {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 1em;\n}\n\n.rz-entry-title {\n  font-size: var(--t-role);\n  font-weight: 650;\n  line-height: 1.3;\n}\n\n.rz-entry-org {\n  font-weight: 500;\n  color: var(--ink-soft);\n}\n\n.rz-entry-line--sub {\n  margin-top: calc(var(--gap-line) * 0.5);\n  font-size: var(--t-meta);\n  color: var(--ink-mute);\n}\n\n.rz-dates {\n  flex: 0 0 auto;\n  font-size: var(--t-meta);\n  color: var(--ink-mute);\n  white-space: nowrap;\n  font-variant-numeric: tabular-nums;\n}\n\n.rz-entry-note {\n  margin-top: var(--gap-line);\n  font-size: var(--t-meta);\n  color: var(--ink-soft);\n}\n\n/* -------------------------------------------------------------- bullets -- */\n\n/* Specificity has to beat the `.rz ul` reset above, or the markers vanish\n   and every bullet reads as a paragraph. */\n.rz .rz-bullets {\n  list-style: disc outside;\n  margin-top: var(--gap-head);\n  padding-left: 1.05em;\n}\n\n.rz .rz-bullets > li {\n  margin-top: var(--gap-line);\n  padding-left: 0.12em;\n  break-inside: avoid;\n  page-break-inside: avoid;\n}\n\n.rz .rz-bullets > li:first-child {\n  margin-top: 0;\n}\n\n.rz .rz-bullets > li::marker {\n  color: var(--ink-mute);\n  font-size: 0.85em;\n}\n\n/* --------------------------------------------------------------- skills -- */\n\n/* A definition list, because that is what it is: a category and its members.\n   The grid keeps every category label on one optical column without the\n   table markup that trips some parsers. */\n.rz-skills {\n  display: grid;\n  grid-template-columns: max-content 1fr;\n  column-gap: 0.85em;\n  row-gap: var(--gap-line);\n}\n\n.rz-skill-row {\n  display: contents;\n}\n\n.rz-skills dt {\n  font-weight: 650;\n  color: var(--ink);\n  break-inside: avoid;\n}\n\n.rz-skills dd {\n  color: var(--ink-soft);\n}\n\n/* Each category is wrapped in a .rz-skill-row so the pair stays together\n   across a page break. The wrapper is display:contents, so the grid still\n   lays dt and dd out as two columns, and that is exactly what made the\n   following bug survive review: every rule here was written as\n   `.rz-skills > dt`, the wrapper broke the child combinator, and NONE of\n   them ever matched. Standard still looked right because the grid alignment\n   comes from the dl, not from these rules, so the only visible symptom was a\n   category label rendering at the same weight as its values, which reads as\n   a design choice rather than a bug. Descendant selectors throughout.\n\n   Stacked variant for a narrow column. */\n.rz-skills--stacked {\n  display: block;\n}\n\n.rz-skills--stacked dt {\n  margin-top: var(--gap-head);\n}\n\n.rz-skills--stacked .rz-skill-row:first-child dt {\n  margin-top: 0;\n}\n\n.rz-skills--stacked dd {\n  font-size: var(--t-small);\n  line-height: 1.4;\n}\n\n/* ------------------------------------------------------------ education -- */\n\n.rz-edu-degree {\n  color: var(--ink-soft);\n  font-size: var(--t-meta);\n  margin-top: calc(var(--gap-line) * 0.5);\n}\n\n.rz .rz-plain {\n  margin: 0;\n  padding-left: 1.05em;\n  list-style: disc outside;\n}\n\n.rz .rz-plain > li::marker {\n  color: var(--ink-mute);\n  font-size: 0.85em;\n}\n\n.rz .rz-plain > li {\n  margin-top: var(--gap-line);\n  break-inside: avoid;\n}\n\n.rz .rz-plain > li:first-child {\n  margin-top: 0;\n}\n\n/* =========================================================================\n   Standard: roomy and conservative. One column, a rule under each heading,\n   dates right-aligned. The safest thing to hand a parser.\n   ========================================================================= */\n\n.rz--standard .rz-header {\n  padding-bottom: calc(var(--block-gap) * 0.7em);\n  margin-bottom: var(--gap-section);\n  border-bottom: 1.4pt solid var(--rule-strong);\n}\n\n/* =========================================================================\n   Compact: the same skeleton, set tighter. For people with more to say.\n   It does not change the type scale, only the air around it, which is the\n   same order the density ladder spends in.\n   ========================================================================= */\n\n.rz--compact {\n  --t-name: 1.6em;\n  --gap-section: calc(var(--block-gap) * 0.82em);\n  --gap-entry: calc(var(--block-gap) * 0.55em);\n  --gap-head: calc(var(--block-gap) * 0.3em);\n  --gap-line: calc(var(--block-gap) * 0.14em);\n  --t-h2: 0.78em;\n}\n\n.rz--compact .rz-header {\n  padding-bottom: calc(var(--block-gap) * 0.45em);\n  margin-bottom: var(--gap-section);\n  border-bottom: 1pt solid var(--rule-strong);\n}\n\n.rz--compact .rz-h2 {\n  letter-spacing: 0.12em;\n}\n\n.rz.rz--compact .rz-bullets {\n  padding-left: 0.95em;\n}\n\n/* =========================================================================\n   Modern: sidebar left for contact, skills and education; main column right\n   for the summary, experience and projects. Handsome, and honestly labelled\n   in the registry as something a parser may read out of order.\n   ========================================================================= */\n\n.rz--modern {\n  --t-name: 1.7em;\n  padding: 0;\n}\n\n.rz--modern .rz-cols {\n  display: grid;\n  /* Wide enough that an email address fits without being broken mid-word,\n     narrow enough that the main column still reads as the main column. */\n  grid-template-columns: 33% 1fr;\n  min-height: var(--page-h);\n  align-items: stretch;\n}\n\n.rz--modern .rz-aside {\n  padding: var(--page-pad) calc(var(--page-pad) * 0.58);\n  background: var(--panel);\n  border-right: 0.6pt solid var(--rule);\n  min-width: 0;\n}\n\n.rz--modern .rz-main {\n  padding: var(--page-pad) var(--page-pad) var(--page-pad) calc(var(--page-pad) * 0.78);\n  min-width: 0;\n}\n\n.rz--modern .rz-header {\n  padding-bottom: calc(var(--block-gap) * 0.6em);\n  margin-bottom: var(--gap-section);\n  border-bottom: 0.6pt solid var(--rule);\n}\n\n.rz--modern .rz-name {\n  color: var(--accent);\n}\n\n.rz--modern .rz-headline {\n  font-size: var(--t-small);\n}\n\n/* Down the sidebar the contact details are a stack, not a line, so the\n   inline separator has to go with the row layout. */\n.rz--modern .rz-contact--stacked {\n  display: block;\n  font-size: var(--t-small);\n}\n\n.rz--modern .rz-contact--stacked > li {\n  margin-top: var(--gap-line);\n  /* A long address wraps rather than widening the column, but only when it\n     genuinely cannot fit, so it is not chopped mid-word by default. */\n  overflow-wrap: break-word;\n}\n\n.rz--modern .rz-contact--stacked > li:not(:last-child)::after {\n  content: none;\n}\n\n.rz--modern .rz-aside .rz-h2 {\n  border-bottom-color: var(--accent);\n  color: var(--accent);\n}\n\n/* In a narrow column a right-aligned date fights the wrapped title it sits\n   beside, so the sidebar stacks what the main column sets on one line. */\n.rz--modern .rz-aside .rz-entry-line {\n  display: block;\n}\n\n.rz--modern .rz-aside .rz-dates {\n  display: block;\n  margin-top: calc(var(--gap-line) * 0.5);\n  white-space: normal;\n}\n\n.rz--modern .rz-aside .rz-skills--stacked dt {\n  font-size: var(--t-small);\n  font-weight: 700;\n  letter-spacing: 0.02em;\n  margin-top: calc(var(--gap-head) * 1.6);\n}\n\n.rz--modern .rz-aside .rz-plain {\n  padding-left: 0.9em;\n  font-size: var(--t-small);\n}\n\n.rz--modern .rz-main .rz-h2 {\n  border-bottom-color: var(--rule-strong);\n}\n\n/* ------------------------------------------------------------ print fix -- */\n\n/*\n  The page reset, outside the print block.\n\n  It used to live only inside `@media print`, which meant the PDF was right\n  and the screen was wrong: the user agent's default 8px body margin made\n  every template 802px wide in a 794px A4 viewport, so the live preview had\n  a horizontal scrollbar that the export did not. The E2E suite caught it on\n  all nine fixtures at once, which is what a preview and its output being\n  the same document is supposed to prevent.\n\n  The background stays white here too. A template is a sheet of paper; it\n  should not pick up the product's page tint when rendered standalone.\n*/\nhtml:has(.rz),\nbody:has(.rz) {\n  margin: 0;\n  padding: 0;\n  background: #ffffff;\n}\n\n@media print {\n  html,\n  body {\n    margin: 0;\n    padding: 0;\n    background: #ffffff;\n  }\n\n  .rz {\n    width: auto;\n    min-height: 0;\n    margin: 0;\n    box-shadow: none;\n  }\n\n  .rz--modern .rz-cols {\n    /* The sidebar fill has to run the full height of every printed page,\n       which a grid row cannot promise once the content breaks. */\n    min-height: var(--page-h);\n  }\n\n  .rz a {\n    text-decoration: none;\n  }\n}\n\n/* On screen the page is an object on a desk, not the whole window. */\n@media screen {\n  .rz {\n    box-shadow: 0 1px 2px rgba(16, 18, 22, 0.08), 0 8px 24px rgba(16, 18, 22, 0.08);\n  }\n}\n";
